#!/bin/bash
# Regenerate the paper figures of the blended scheme with the quadratic band extension
# (pyRMT.functions.EXTRAP_ORDER = 2) on top of the bug-fixed solver. The plane-fit results are
# archived in outputs/archive_planefit_2026-11/ before anything is overwritten.
# One job at a time, lowest priority, NTHREADS threads (the machine is shared). Resumable: each
# stage writes a marker in outputs/quadext_2026-11/done/ and is skipped when re-launched.
# Not here: the disc-in-vortex convergence figure (blended and sharp), which is generated by
# benchmarks/iim_paper_figures.py on the sharp-interface branch.
cd "$(dirname "$0")/../.." || exit 1
NT=${NTHREADS:-2}
export NUMBA_NUM_THREADS=$NT OMP_NUM_THREADS=$NT MKL_NUM_THREADS=$NT OPENBLAS_NUM_THREADS=$NT
export RERUN_DIR=quadext_2026-11
OUT=outputs/quadext_2026-11; LOG=$OUT/regen.log; DONE=$OUT/done; ARC=outputs/archive_planefit_2026-11
mkdir -p "$DONE" "$OUT/paper_numbers"
if [ ! -d "$ARC" ]; then          # archive the plane-fit data and figures once
  mkdir -p "$ARC/figures"; cp -a outputs/overlay "$ARC/overlay"; cp -a paper/figures/*.png "$ARC/figures/"
  echo "$(date +%H:%M) archived plane-fit data to $ARC" >> "$LOG"
fi
stage () {  # stage <name> <command...>
  local name=$1; shift
  if [ -f "$DONE/$name" ]; then echo "$(date +%H:%M) skip $name" >> "$LOG"; return; fi
  echo "$(date +%H:%M) START $name" >> "$LOG"
  if nice -n 19 "$@" >> "$LOG" 2>&1; then
    touch "$DONE/$name"; echo "$(date +%H:%M) DONE $name" >> "$LOG"
  else
    echo "$(date +%H:%M) FAILED $name (exit $?)" >> "$LOG"
  fi
}
# caches the contact generators would otherwise reuse (archived copies are kept above)
for f in contact_conv contact_collision contact_collision_snaps; do
  [ -f "$DONE/contact_convergence" ] || [ -f "$DONE/cleared_$f" ] || { rm -f outputs/overlay/$f.npz; touch "$DONE/cleared_$f"; }
done

stage lid_tauinf         python3 -u benchmarks/lid_stab_and_tauinf.py
stage lid_overlay        python3 -u -c "import sys; sys.path.insert(0,'benchmarks'); sys.path.insert(0,'.'); from benchmarks.overlay_integrators import soft_disc_overlay; print(soft_disc_overlay())"
stage lid_overlay_copy   cp outputs/overlay/soft_disc_overlay.png paper/figures/soft_disc_overlay.png
stage energy_benchmark   python3 -u benchmarks/disc_tg_energy_figure.py
stage numbers_energy     python3 -u benchmarks/reruns/paper_numbers.py energy
stage sls_energy         python3 -u benchmarks/sls_energy_figure.py
stage numbers_detbe      python3 -u benchmarks/reruns/paper_numbers.py detbe
stage ve_snapshots       python3 -u benchmarks/ve_snapshots_figure.py
stage drift              python3 -u benchmarks/drift_diagnostics.py
stage temporal           python3 -u benchmarks/temporal_convergence.py
stage work_precision     python3 -u benchmarks/reruns/paper_numbers.py work_precision
stage lid_snapshots      bash -c "cd benchmarks && python3 -u soft_disc_lid_snapshots.py"
stage numbers_bilinear   python3 -u benchmarks/reruns/paper_numbers.py bilinear
stage contact_convergence python3 -u benchmarks/contact_convergence.py
stage contact_figure     python3 -u benchmarks/contact_figure.py
stage numbers_momentum   python3 -u benchmarks/reruns/paper_numbers.py momentum
stage shear_fourroll     python3 -u benchmarks/reruns/shear_and_fourroll.py
stage shear_long         python3 -u benchmarks/reruns/shear_long_highWi.py
stage fourroll_quarter   python3 -u benchmarks/reruns/fourroll_elastic_quarter_dt.py
stage shear_figure       python3 -u benchmarks/disc_in_shear_figure.py
stage fourroll_figure    bash -c "cd benchmarks && python3 -u ve_extension_figure.py"
stage numbers_summary    python3 -u benchmarks/reruns/paper_numbers.py summary
echo "$(date +%H:%M) REGENERATION FINISHED" >> "$LOG"
